class Solution {
public:
    vector<int> minEdgeReversals(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], 0}); // edge parent->child direction
            adj[e[1]].push_back({e[0], 1}); // edge child->parent direction
        }
        vector<int> dp(n, 0), par(n, -1), parDir(n, 0), order;
        vector<char> vis(n, 0);
        order.reserve(n);
        vector<int> q;
        q.reserve(n);
        q.push_back(0);
        vis[0] = 1;
        for (size_t i = 0; i < q.size(); ++i) {
            int x = q[i];
            order.push_back(x);
            for (auto& [y, d] : adj[x]) {
                if (!vis[y]) {
                    vis[y] = 1;
                    par[y] = x;
                    parDir[y] = d;
                    q.push_back(y);
                }
            }
        }
        for (int i = n - 1; i >= 1; --i) {
            int x = order[i];
            dp[par[x]] += dp[x] + parDir[x];
        }
        vector<int> ans(n);
        ans[0] = dp[0];
        for (int i = 1; i < n; ++i) {
            int x = order[i];
            ans[x] = ans[par[x]] + (parDir[x] == 0 ? 1 : -1);
        }
        return ans;
    }
};
